# Expected values are SymPy's outputs for the same calls (sympy/integrals/tests/test_quadrature.py);
# the rows come from the battery that compares this port with SymPy.

test_that("quadrature: gauss_chebyshev_u", {
  expect_identical(.pyrun(local({ .pyT(gauss_chebyshev_u(1, 17)) })), "([0], [1.5707963267948966])")
})

test_that("quadrature: gauss_gen_laguerre", {
  expect_identical(.pyrun(local({ .pyT(gauss_gen_laguerre(1, 2, 17)) })), "([3.0000000000000000], [2.0000000000000000])")
  expect_identical(.pyrun(local({ .pyT(gauss_gen_laguerre(2, 2, 17)) })), "([2.0000000000000000, 6.0000000000000000], [1.5000000000000000, 0.50000000000000000])")
  expect_identical(.pyrun(local({ .pyT(gauss_gen_laguerre(2, Rational(-1, 2), 17)) })), "([0.27525512860841095, 2.7247448713915890], [1.6098281800110257, 0.16262567089449035])")
  expect_identical(.pyrun(local({ .pyT(gauss_gen_laguerre(3, 2, 17)) })), "([1.5173870806774125, 4.3115831337195203, 9.1710297856030672], [1.0374949614904253, 0.90575000470306537, 0.056755033806509347])")
  expect_identical(.pyrun(local({ .pyT(gauss_gen_laguerre(3, 2, 40)) })), "([1.517387080677412495020323111016672547482, 4.311583133719520302881184669723530562299, 9.171029785603067202098492219259796890218], [1.037494961490425285817554606541269153041, 0.9057500047030653669269785048806009945254, 0.05675503380650934725546688857812985243312])")
  expect_identical(.pyrun(local({ .pyT(gauss_gen_laguerre(4, 2, 17)) })), "([1.2267632635003021, 3.4125073586969460, 6.9026926058516134, 12.458036771951139], [0.72552499769865438, 1.0634242919791946, 0.20669613102835355, 0.0043545792937974889])")
  expect_identical(.pyrun(local({ .pyT(gauss_gen_laguerre(2, 1, 10)) })), "([1.267949192, 4.732050808], [0.7886751346, 0.2113248654])")
})

test_that("quadrature: gauss_hermite", {
