  expect_identical(.pyrun(local({ .pyT(gauss_jacobi(1, Rational(-1, 2), Rational(1, 2), 17)) })), "([0.50000000000000000], [3.1415926535897932])")
  expect_identical(.pyrun(local({ .pyT(gauss_jacobi(2, 2, 3, 17)) })), "([-0.24025307335204215, 0.46247529557426437], [0.48514624517838660, 0.58152042148828007])")
  expect_identical(.pyrun(local({ .pyT(gauss_jacobi(2, Rational(-1, 2), Rational(1, 2), 17)) })), "([-0.30901699437494742, 0.80901699437494742], [0.86831485369082398, 2.2732777998989693])")
  expect_identical(.pyrun(local({ .pyT(gauss_jacobi(3, 2, 3, 40)) })), "([-0.4611587037808976179121958105554375981274, 0.1043853303832390210914918407615869143233, 0.6295006461249313240934312425211234110769], [0.1793761350221326596137764371503859752628, 0.6159564099114715430909548532229749439714, 0.2713341217330624639619353762933057474325])")
  expect_identical(.pyrun(local({ .pyT(gauss_jacobi(3, Rational(-1, 2), Rational(1, 2), 17)) })), "([-0.62348980185873353, 0.22252093395631440, 0.90096886790241913], [0.33795476356635433, 1.0973322242791115, 1.7063056657443274])")
  expect_identical(.pyrun(local({ .pyT(gauss_jacobi(3, 0, 0, 15)) })), "([-0.774596669241483, 0, 0.774596669241483], [0.555555555555556, 0.888888888888889, 0.555555555555556])")
  expect_identical(.pyrun(local({ .pyT(gauss_jacobi(2, 1, 1, 10)) })), "([-0.4472135955, 0.4472135955], [0.6666666667, 0.6666666667])")
})

