test_that("quadrature: gauss_lobatto", {
  expect_identical(.pyrun(local({ .pyT(gauss_lobatto(2, 17)) })), "([-1, 1], [1.0000000000000000, 1.0000000000000000])")
  expect_identical(.pyrun(local({ .pyT(gauss_lobatto(3, 17)) })), "([-1, 0, 1], [0.33333333333333333, 1.3333333333333333, 0.33333333333333333])")
  expect_identical(.pyrun(local({ .pyT(gauss_lobatto(3, 40)) })), "([-1, 0, 1], [0.3333333333333333333333333333333333333333, 1.333333333333333333333333333333333333333, 0.3333333333333333333333333333333333333333])")
  expect_identical(.pyrun(local({ .pyT(gauss_lobatto(4, 17)) })), "([-1, -0.44721359549995794, 0.44721359549995794, 1], [0.16666666666666667, 0.83333333333333333, 0.83333333333333333, 0.16666666666666667])")
  expect_identical(.pyrun(local({ .pyT(gauss_lobatto(5, 17)) })), "([-1, -0.65465367070797714, 0, 0.65465367070797714, 1], [0.10000000000000000, 0.54444444444444444, 0.71111111111111111, 0.54444444444444444, 0.10000000000000000])")
  expect_identical(.pyrun(local({ .pyT(gauss_lobatto(6, 10)) })), "([-1, -0.7650553239, -0.2852315165, 0.2852315165, 0.7650553239, 1], [0.06666666667, 0.3784749563, 0.5548583770, 0.5548583770, 0.3784749563, 0.06666666667])")
  expect_identical(.pyrun(local({ .pyT(gauss_lobatto(7, 15)) })), "([-1, -0.830223896278567, -0.468848793470714, 0, 0.468848793470714, 0.830223896278567, 1], [0.0476190476190476, 0.276826047361566, 0.431745381209863, 0.487619047619048, 0.431745381209863, 0.276826047361566, 0.0476190476190476])")
